head.b:skin:
/* =================================================================
   JAYANT'S AI LAB — SUBSTACK & LINEAR MINIMAL EDITORIAL XML THEME
   ================================================================= */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  background-color: #ffffff;
  color: #111827;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 17px;
  line-height: 1.75;
  -webkit-font-smoothing: antialiased;
}
a { color: #0f172a; text-decoration: none; transition: color 0.15s ease; }
a:hover { color: #00c853; }

/* Header */
.site-header {
  border-bottom: 1px solid #e2e8f0;
  padding: 36px 20px 24px;
  text-align: center;
  background: #ffffff;
}
.site-title {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: #0f172a;
  display: inline-block;
}
.site-tagline {
  font-size: 15px;
  color: #64748b;
  margin-top: 6px;
  font-weight: 400;
}

/* Main Container */
.container {
  max-width: 760px;
  margin: 0 auto;
  padding: 40px 20px 80px;
}

/* Post Card / Post Outer */
.post {
  margin-bottom: 48px;
  padding-bottom: 40px;
  border-bottom: 1px solid #f1f5f9;
}
.post-title {
  font-size: 28px;
  font-weight: 800;
  line-height: 1.3;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}
.post-title a { color: #0f172a; }
.post-title a:hover { color: #00c853; }

.post-meta {
  font-size: 13px;
  color: #94a3b8;
  margin-bottom: 24px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.post-badge {
  background: #e6f9ed;
  color: #00873a;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 4px;
  letter-spacing: 0.05em;
}

/* Post Content Typography */
.post-body {
  font-size: 17px;
  line-height: 1.8;
  color: #1f2937;
}
.post-body h2 {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #0f172a;
  margin: 40px 0 16px;
  border-bottom: 1px solid #f1f5f9;
  padding-bottom: 8px;
}
.post-body h3 {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: #1e293b;
  margin: 32px 0 12px;
}
.post-body p { margin-bottom: 22px; }
.post-body ul, .post-body ol { padding-left: 24px; margin-bottom: 24px; }
.post-body li { margin-bottom: 8px; }
.post-body strong { color: #0f172a; font-weight: 600; }
.post-body img { max-width: 100%; height: auto; border-radius: 12px; margin: 24px 0; box-shadow: 0 4px 16px rgba(0,0,0,0.06); }

/* Code & Quotes */
.post-body pre {
  background: #0d1117;
  color: #00ffaa;
  padding: 20px;
  border-radius: 10px;
  overflow-x: auto;
  font-family: 'JetBrains Mono', monospace;
  font-size: 14px;
  line-height: 1.5;
  margin: 28px 0;
  border: 1px solid #30363d;
}
.post-body blockquote {
  border-left: 4px solid #00c853;
  background: #f8fafc;
  padding: 16px 20px;
  margin: 28px 0;
  border-radius: 0 8px 8px 0;
  font-style: italic;
  color: #334155;
}

/* Pager */
.blog-pager { text-align: center; margin-top: 40px; }
.blog-pager a {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 8px;
  background: #f1f5f9;
  color: #0f172a;
  font-weight: 600;
  font-size: 14px;
  margin: 0 6px;
}
.blog-pager a:hover { background: #e2e8f0; }

/* Footer */
.site-footer {
  border-top: 1px solid #e2e8f0;
  padding: 30px 20px;
  text-align: center;
  font-size: 14px;
  color: #64748b;
  background: #fafafa;
}
